def sequence_powers_of_2(limit):
    n_values = []
    for a in range(1, 10):
        n = 2**a - 2
        if n < limit:
            n_values.append(n)
        else:
            break
    return n_values

def sequence_powers_of_5(limit):
    n_values = []
    for b in range(1, 10):
        n = 5**b - 2
        if n < limit:
            n_values.append(n)
        else:
            break
    return n_values

print("n based on powers of 2 (a<10):", sequence_powers_of_2(1000))
print("n based on powers of 5 (b<10):", sequence_powers_of_5(1000))

