import math

def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def is_2_5_smooth(k):
    if k <= 0:
        return False
    if k == 1:
        return True

    temp_k = k
    while temp_k % 2 == 0:
        temp_k //= 2
    while temp_k % 5 == 0:
        temp_k //= 5

    return temp_k == 1

solutions = []
for n in range(21):
    d_n = D(n)

    if not is_2_5_smooth(d_n):
        continue

    # If D(n) is 2-5 smooth, we check the exponent condition.
    if d_n == 1:
        # D(n) = 1 is impossible for n >= 0 since D(0)=4.
        pass
    else:
        # Count powers of 2 and 5 in d_n
        a = 0
        b = 0
        temp_d_n = d_n
        while temp_d_n % 2 == 0:
            a += 1
            temp_d_n //= 2
        while temp_d_n % 5 == 0:
            b += 1
            temp_d_n //= 5

        # Exponents required: a <= 2(n+1) and b <= n+1

        # The required exponents from 20^(n+1) = 2^(2n+2) * 5^(n+1)
        max_a = 2 * (n + 1)
        max_b = n + 1

        if a <= max_a and b <= max_b:
            solutions.append(n)

print("Solutions found (n <= 20):", solutions)
